		{name: "string healthy", body: map[string]any{"healthy": "true"}},
		{name: "uppercase text healthy", body: map[string]any{"healthy": "TRUE"}},
		{name: "query uppercase true", path: "/api/v1/services/svc/instances/i-1/health?healthy=True", query: true},
		{name: "query number", path: "/api/v1/services/svc/instances/i-1/health?healthy=1", query: true},
		{name: "query yes", path: "/api/v1/services/svc/instances/i-1/health?healthy=yes", query: true},
		{name: "query whitespace", path: "/api/v1/services/svc/instances/i-1/health?healthy=%20true", query: true},
		{name: "missing everywhere", query: true},
		{name: "empty body", body: nil},
		{name: "body not an object", rawBody: "[true]"},
		{name: "body malformed json", rawBody: "{bad"},
		{name: "bad body even with valid query", path: "/api/v1/services/svc/instances/i-1/health?healthy=false", rawBody: "{bad"},
		{name: "empty service name", path: "/api/v1/services//instances/i-1/health", body: map[string]any{"healthy": false}},
		{name: "empty instance id", path: "/api/v1/services/svc/instances//health", body: map[string]any{"healthy": false}},
		{name: "blank instance id in query path", path: "/api/v1/services/svc/instances//health?healthy=false", query: true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path := tc.path
			if path == "" {
				path = "/api/v1/services/svc/instances/i-1/health"
			}
			var rec *httptest.ResponseRecorder
			switch {
			case tc.rawBody != "":
